WITH store_stats AS ( SELECT ss.ss_store_sk, ib.ib_income_band_sk, ib.ib_lower_bound, ib.ib_upper_bound, COUNT(DISTINCT hd.hd_demo_sk) AS household_count, AVG(ss.ss_ext_discount_amt) AS avg_discount_amount, SUM(ss.ss_ext_sales_price) AS total_sales, SUM(ss.ss_ext_sales_price) - SUM(ss.ss_ext_list_price) AS discount_vs_list, CASE WHEN SUM(ss.ss_ext_sales_price) > 1000000 THEN 'High Sales' WHEN SUM(ss.ss_ext_sales_price) > 500000 THEN 'Medium Sales' ELSE 'Low Sales' END AS sales_category FROM store_sales ss JOIN household_demographics hd ON ss.ss_hdemo_sk = hd.hd_demo_sk JOIN income_band ib ON hd.hd_income_band_sk = ib.ib_income_band_sk WHERE hd.hd_vehicle_count > 0 GROUP BY ss.ss_store_sk, ib.ib_income_band_sk, ib.ib_lower_bound, ib.ib_upper_bound HAVING COUNT(*) > 10 ) SELECT ss_store_sk, ib_income_band_sk, ib_lower_bound, ib_upper_bound, household_count, avg_discount_amount, total_sales, discount_vs_list, DENSE_RANK() OVER (ORDER BY avg_discount_amount DESC) AS discount_rank, sales_category FROM store_stats ORDER BY discount_rank
